import java.math.BigDecimal;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

public class MovieBookingEngine {
    public enum SeatState { AVAILABLE, HELD, BOOKED }
    public enum SeatTier { REGULAR, PREMIUM, RECLINER }

    public static final class ShowSeat {
        final String seatId;
        final SeatTier tier;
        final ReentrantLock lock = new ReentrantLock();
        SeatState state = SeatState.AVAILABLE;
        String leaseId;
        long fencingToken;
        long expiresAtMs;
        ShowSeat(String seatId, SeatTier tier) { this.seatId = seatId; this.tier = tier; }
    }

    public record BookingHold(String leaseId, long fencingToken, List<String> seatIds, BigDecimal quotedTotal, long expiresAtMs) {}
    public interface PricingStrategy { BigDecimal apply(BigDecimal current, double occupancyRatio, SeatTier tier); }

    private final Map<String, ShowSeat> seats = new ConcurrentHashMap<>();
    private final Map<String, BookingHold> holds = new ConcurrentHashMap<>();
    private final Map<String, String> confirmedByIdempotency = new ConcurrentHashMap<>();
    private final AtomicLong tokenSeq = new AtomicLong(0);
    private final List<PricingStrategy> pricingPipeline;
    private final Clock clock;

    public MovieBookingEngine(List<PricingStrategy> pricingPipeline, Clock clock) {
        this.pricingPipeline = pricingPipeline;
        this.clock = clock;
    }

    public BookingHold holdSeats(List<String> requestedSeats, long ttlMs) {
        List<String> sorted = requestedSeats.stream().distinct().sorted().toList();
        List<ReentrantLock> acquired = new ArrayList<>(sorted.size());
        long now = clock.millis();
        try {
            for (String id : sorted) {
                ShowSeat seat = seats.get(id);
                if (seat == null) throw new IllegalArgumentException("Unknown seat: " + id);
                seat.lock.lock();
                acquired.add(seat.lock);
            }
            for (String id : sorted) {
                ShowSeat seat = seats.get(id);
                if (seat.state == SeatState.HELD && now > seat.expiresAtMs) {
                    seat.state = SeatState.AVAILABLE;
                    seat.leaseId = null;
                }
                if (seat.state != SeatState.AVAILABLE) {
                    throw new IllegalStateException("Seat unavailable: " + id);
                }
            }
            double occupancy = seats.values().stream().filter(s -> s.state != SeatState.AVAILABLE).count() / (double) Math.max(1, seats.size());
            BigDecimal total = BigDecimal.ZERO;
            for (String id : sorted) {
                BigDecimal price = BigDecimal.valueOf(250);
                SeatTier tier = seats.get(id).tier;
                for (PricingStrategy s : pricingPipeline) price = s.apply(price, occupancy, tier);
                total = total.add(price);
            }
            String leaseId = UUID.randomUUID().toString();
            long token = tokenSeq.incrementAndGet();
            long expiresAt = now + ttlMs;
            for (String id : sorted) {
                ShowSeat seat = seats.get(id);
                seat.state = SeatState.HELD;
                seat.leaseId = leaseId;
                seat.fencingToken = token;
                seat.expiresAtMs = expiresAt;
            }
            BookingHold hold = new BookingHold(leaseId, token, sorted, total, expiresAt);
            holds.put(leaseId, hold);
            return hold;
        } finally {
            for (int i = acquired.size() - 1; i >= 0; i--) acquired.get(i).unlock();
        }
    }

    public String confirmBooking(String leaseId, long fencingToken, String idempotencyKey) {
        String existing = confirmedByIdempotency.get(idempotencyKey);
        if (existing != null) return existing;
        BookingHold hold = Optional.ofNullable(holds.get(leaseId)).orElseThrow();
        List<ReentrantLock> acquired = new ArrayList<>();
        long now = clock.millis();
        try {
            for (String id : hold.seatIds()) {
                ShowSeat seat = seats.get(id);
                seat.lock.lock();
                acquired.add(seat.lock);
            }
            for (String id : hold.seatIds()) {
                ShowSeat seat = seats.get(id);
                if (seat.state != SeatState.HELD || !leaseId.equals(seat.leaseId) || seat.fencingToken != fencingToken || now > seat.expiresAtMs) {
                    throw new IllegalStateException("Lease expired or superseded; trigger refund");
                }
            }
            for (String id : hold.seatIds()) seats.get(id).state = SeatState.BOOKED;
            String bookingId = "BK-" + leaseId.substring(0, 8);
            confirmedByIdempotency.put(idempotencyKey, bookingId);
            return bookingId;
        } finally {
            for (int i = acquired.size() - 1; i >= 0; i--) acquired.get(i).unlock();
        }
    }
}

